// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();



export type NeonCounterProps = Record<string, any>;

const NeonCounter: React.FC<NeonCounterProps> = ({
  backgroundColor = "#08080c",
  transparentBackground = false,
  durationInSeconds = 4,
  startNumber = 520,
  endNumber = 600,
  topText = "MINIMUM SCORE",
  bottomText = "LET'S GET THERE",
  glowColor = "#ccff00",
  textColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timing Calculations
  const totalFrames = Math.floor(durationInSeconds * fps);
  const slamFrame = Math.floor(totalFrames * 0.5); // Animation hits the climax exactly halfway through
  const introEnd = Math.floor(slamFrame * 0.25);

  // Intro text animations
  const topTextOpacity = interpolate(frame, [0, introEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const topTextY = interpolate(frame, [0, introEnd], [30, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.quad),
  });

  const bottomIntroStart = Math.floor(introEnd * 0.5);
  const bottomIntroEnd = bottomIntroStart + introEnd;
  const bottomTextOpacity = interpolate(frame, [bottomIntroStart, bottomIntroEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const bottomTextY = interpolate(frame, [bottomIntroStart, bottomIntroEnd], [30, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.quad),
  });

  // Counter logic: Easing.in(Easing.cubic) starts slow and hits max velocity right at the slamFrame
  const countProgress = interpolate(frame, [introEnd, slamFrame], [0, 1], {
    easing: Easing.in(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const currentVal = Math.floor(interpolate(countProgress, [0, 1], [startNumber, endNumber]));

  // Slam & Flash impact logic
  const hitStop = frame >= slamFrame;

  // Screen shake on impact
  const shakeX = hitStop
    ? interpolate(
        frame,
        [slamFrame, slamFrame + 2, slamFrame + 4, slamFrame + 6, slamFrame + 8],
        [0, -15, 12, -8, 0],
        { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
      )
    : 0;

  const shakeY = hitStop
    ? interpolate(
        frame,
        [slamFrame, slamFrame + 2, slamFrame + 4, slamFrame + 6, slamFrame + 8],
        [0, 10, -10, 5, 0],
        { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
      )
    : 0;

  // Micro-scale pop of the number itself
  const numScaleX = interpolate(frame, [slamFrame, slamFrame + 3, slamFrame + 15], [1, 1.1, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const numScaleY = interpolate(frame, [slamFrame, slamFrame + 3, slamFrame + 15], [1, 1.05, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Giant neon pulse behind the text
  const glowScale = interpolate(frame, [slamFrame, slamFrame + 8, slamFrame + 25], [1, 1.4, 1.6], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const glowOpacity = interpolate(frame, [slamFrame, slamFrame + 5, slamFrame + 25], [0, 0.8, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Inner text shadow flare
  const textShadowBlur1 = interpolate(frame, [slamFrame, slamFrame + 5, slamFrame + 20], [0, 20, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const textShadowBlur2 = interpolate(frame, [slamFrame, slamFrame + 5, slamFrame + 20], [0, 60, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const numberShadow =
    frame >= slamFrame && textShadowBlur1 > 0
      ? `0 0 ${textShadowBlur1}px ${glowColor}, 0 0 ${textShadowBlur2}px ${glowColor}`
      : "none";

  // Environmental flash
  const bgFlashOpacity = interpolate(frame, [slamFrame, slamFrame + 2, slamFrame + 20], [0, 0.15, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Subtle continuous motion
  const bgTranslateY = interpolate(frame, [0, totalFrames], [0, 80]);
  const globalScale = interpolate(frame, [0, totalFrames], [0.95, 1.05]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* --- GEOMETRIC BACKGROUND --- */}
      <AbsoluteFill style={{ opacity: 0.4, transition: "none" }}>
        <svg width="100%" height="100%">
          <defs>
            <pattern
              id="gridPattern"
              width="80"
              height="80"
              patternUnits="userSpaceOnUse"
              patternTransform={`translate(0, ${bgTranslateY})`}
            >
              <path d="M 80 0 L 0 0 0 80" fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth="2" />
              <path d="M 40 0 L 40 80 M 0 40 L 80 40" fill="none" stroke="rgba(255,255,255,0.03)" strokeWidth="1" />
              <circle cx="0" cy="0" r="4" fill={glowColor} fillOpacity={0.2} />
            </pattern>
          </defs>
          <rect width="100%" height="100%" fill="url(#gridPattern)" />
        </svg>
      </AbsoluteFill>

      {/* Vignette Overlay */}
      <AbsoluteFill
        style={{
          background: "radial-gradient(circle at 50% 50%, rgba(0,0,0,0) 20%, rgba(0,0,0,0.85) 100%)",
        }}
      />
      
      {/* Environmental Hit Flash */}
      <AbsoluteFill
        style={{
          backgroundColor: glowColor,
          opacity: bgFlashOpacity,
          mixBlendMode: "overlay",
          transition: "none",
        }}
      />

      {/* --- FOREGROUND CONTENT --- */}
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          transform: `scale(${globalScale}) translate(${shakeX}px, ${shakeY}px)`,
          transition: "none",
        }}
      >
        {/* Top Text */}
        <div
          style={{
            opacity: topTextOpacity,
            transform: `translateY(${topTextY}px)`,
            fontFamily: interFamily,
            fontSize: 36,
            fontWeight: 600,
            letterSpacing: "0.25em",
            color: "rgba(255,255,255,0.6)",
            marginBottom: 40,
            transition: "none",
          }}
        >
          {topText}
        </div>

        {/* Dynamic Number Container */}
        <div
          style={{
            position: "relative",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            transition: "none",
          }}
        >
          {/* Intense Glow Pulse (Background Layer) */}
          <div
            style={{
              position: "absolute",
              opacity: glowOpacity,
              transform: `scale(${glowScale})`,
              filter: "blur(30px)",
              color: glowColor,
              fontFamily: spaceGroteskFamily,
              fontSize: 320,
              fontWeight: 800,
              lineHeight: 1,
              zIndex: 1,
              transition: "none",
            }}
          >
            {currentVal}
          </div>

          {/* Core Number (Foreground Layer) */}
          <div
            style={{
              position: "relative",
              color: textColor,
              textShadow: numberShadow,
              transform: `scale(${numScaleX}, ${numScaleY})`,
              fontFamily: spaceGroteskFamily,
              fontSize: 320,
              fontWeight: 800,
              lineHeight: 1,
              zIndex: 2,
              transition: "none",
            }}
          >
            {currentVal}
          </div>
        </div>

        {/* Bottom Text */}
        <div
          style={{
            opacity: bottomTextOpacity,
            transform: `translateY(${bottomTextY}px)`,
            fontFamily: interFamily,
            fontSize: 48,
            fontWeight: 800,
            letterSpacing: "0.08em",
            color: textColor,
            marginTop: 60,
            background: "rgba(255,255,255,0.1)",
            padding: "20px 48px",
            borderRadius: "100px",
            border: "1px solid rgba(255,255,255,0.2)",
            boxShadow: `0 10px 30px rgba(0,0,0,0.5)`,
            transition: "none",
          }}
        >
          {bottomText}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default NeonCounter;